// Auto-generated bundle of all documentation files for reliable SSR / standalone production builds

export const DOCS_BUNDLE: Record<string, string> = {
  "en/getting-started/architecture": "---\ntitle: System Architecture\ndescription: Internal data flow, hexagonal architecture, and infrastructure components of Betty.\n---\n\nBetty is architected with **Clean Architecture (Hexagonal)** principles to deliver high concurrency, strict isolation, and sub-millisecond Pub/Sub delivery.\n\n---\n\n## 🏗️ Architecture Stack\n\n1. **EMQX 5.8 (MQTT Broker)**: Ingests telemetry via TCP (1883), WSS (8084), and authenticated HTTP webhooks.\n2. **Betty API (NestJS 11)**: Validates payloads, coordinates persistence, and manages role permissions.\n3. **TimescaleDB (PostgreSQL 16)**: Time-series hypertables with temporal partitioning for high-speed queries.\n4. **Dragonfly**: Ultra-fast in-memory cache and multithreaded Pub/Sub broker.\n5. **Realtime Gateway (Socket.IO)**: Bridges Dragonfly Pub/Sub channels to browser dashboards with low latency.\n",
  "en/getting-started/introduction": "---\ntitle: Introduction to Betty PaaS\ndescription: Architectural overview of Betty open source platform for IoT and Digital Twins.\n---\n\n**Betty PaaS** is an open-source platform-as-a-service engineered for high-throughput telemetry ingestion, time-series storage, real-time visual dashboards, and native digital twin metaverse synchronization.\n\n---\n\n## 🎯 Why Betty?\n\n- **Extreme Ingestion Throughput**: Powered by **EMQX 5.8** MQTT broker with per-sensor HTTP cryptographic auth.\n- **Fast Analytical Time-Series**: **PostgreSQL 16 + TimescaleDB** hypertables with automatic temporal partitioning.\n- **Multi-Threaded In-Memory Bus**: **Dragonfly** (Redis-compatible) for ultra-low latency Pub/Sub and caching.\n- **Dual Role RBAC**: System roles (`admin`, `user`) and Workspace/Team roles (`owner`, `team_admin`, `member`, `viewer`).\n- **Browser-Based USB Flashing**: Upload firmware binaries `.bin` and flash ESP32/ESP8266 devices directly through the Web Serial API with interactive 3D model viewers.\n",
  "en/getting-started/quickstart": "---\ntitle: Quickstart in 5 Minutes\ndescription: Register your first sensor and transmit live telemetry to Betty.\n---\n\nConnect your physical hardware device or simulation to Betty and watch data stream in real-time.\n\n---\n\n## 🚀 Step 1: Register a Sensor\n\n1. Log into your Betty web dashboard.\n2. Navigate to **Sensors** and click **+ New Sensor**.\n3. Provide a name and choose the origin type (`Physical Sensor` or `Metaverse / Simulation`).\n4. Copy the generated **cryptographic API Key** (`betty_live_...`) immediately.\n\n---\n\n## 📡 Step 2: Publish via MQTT\n\n- **Broker**: `localhost:1883`\n- **Username**: Sensor UUID (e.g., `4c40ea57-43e0-4ee2-a8d5-77aae4fc387b`)\n- **Password**: API Key (`betty_live_...`)\n- **Topic**: `betty/sensor/<sensorId>/data`\n\n### Using `mosquitto_pub`:\n\n```bash\nmosquitto_pub \\\n  -h localhost \\\n  -p 1883 \\\n  -u \"4c40ea57-43e0-4ee2-a8d5-77aae4fc387b\" \\\n  -P \"betty_live_xxxxxxxxxxxxxxxxxxxxxxxx\" \\\n  -t \"betty/sensor/4c40ea57-43e0-4ee2-a8d5-77aae4fc387b/data\" \\\n  -m '{\"temperature\": 24.5, \"humidity\": 60.2, \"origin_type\": \"sensor\"}'\n```\n",
  "en/hardware/esp32": "---\ntitle: ESP32 Hardware Guide (C++/Arduino)\ndescription: Complete firmware template for connecting ESP32 to Betty PaaS.\n---\n\n## 💻 Sample Code\n\n```cpp\n#include <WiFi.h>\n#include <PubSubClient.h>\n#include <ArduinoJson.h>\n\nconst char* ssid = \"YOUR_WIFI_SSID\";\nconst char* password = \"YOUR_WIFI_PASSWORD\";\nconst char* mqtt_server = \"192.168.1.100\";\nconst int mqtt_port = 1883;\n\nconst char* sensor_id = \"4c40ea57-43e0-4ee2-a8d5-77aae4fc387b\";\nconst char* api_key = \"betty_live_...\";\nconst char* mqtt_topic = \"betty/sensor/4c40ea57-43e0-4ee2-a8d5-77aae4fc387b/data\";\n\nWiFiClient espClient;\nPubSubClient client(espClient);\n\nvoid setup() {\n  Serial.begin(115200);\n  WiFi.begin(ssid, password);\n  while (WiFi.status() != WL_CONNECTED) delay(500);\n  client.setServer(mqtt_server, mqtt_port);\n}\n\nvoid loop() {\n  if (!client.connected()) {\n    while (!client.connect(sensor_id, sensor_id, api_key)) delay(5000);\n  }\n  client.loop();\n\n  StaticJsonDocument<200> doc;\n  doc[\"temperature\"] = 24.5;\n  doc[\"humidity\"] = 58.0;\n  doc[\"origin_type\"] = \"sensor\";\n\n  char buffer[256];\n  serializeJson(doc, buffer);\n  client.publish(mqtt_topic, buffer);\n  delay(5000);\n}\n```\n",
  "en/hardware/esp8266": "---\ntitle: ESP8266 Hardware Guide (NodeMCU)\ndescription: Sample firmware and setup for ESP8266 microcontrollers.\n---\n\nThe ESP8266 communicates with Betty using the standard `PubSubClient` and `ESP8266WiFi` libraries over port 1883 with the sensor's API Key.\n",
  "en/hardware/sensors-guide": "---\ntitle: Compatible Physical Sensors\ndescription: Wiring and JSON data structures for popular environmental and motion sensors.\n---\n\n- **BME280 (I2C)**: Temperature, humidity, barometric pressure.\n- **MPU6050 (I2C)**: 6-Axis accelerometer and gyroscope for real-time 3D motion tracking.\n- **DHT22**: Temperature and relative humidity.\n- **BH1750**: Digital ambient light intensity in Lux.\n",
  "en/metaverses/digital-twins": "---\ntitle: Digital Twins Concept\ndescription: Correlating physical sensor data with 3D virtual metaverse twins.\n---\n\nBetty provides native discrimination between physical sensors (`origin_type: \"sensor\"`) and virtual simulations (`origin_type: \"metaverso\"`), allowing live real-world metrics to drive 3D interactive representations.\n",
  "en/metaverses/threejs-integration": "---\ntitle: Three.js Real-Time 3D Integration\ndescription: Binding 3D CAD models to live WebSocket telemetry.\n---\n\nConnect your WebGL / Three.js 3D application to the Betty Realtime Gateway (`/realtime`) to animate meshes, change shader uniforms, and update models dynamically based on live sensor readings.\n",
  "en/metaverses/unity-unreal": "---\ntitle: 3D Engines Integration (Unity / Unreal Engine)\ndescription: Connecting game engines and metaverse simulations to Betty PaaS.\n---\n\nPublish simulated object telemetry from Unity (via `M2Mqtt` C#) or Unreal Engine (via the MQTT plugin) with `origin_type: \"metaverso\"` on topic `betty/sensor/:id/data`.\n",
  "en/projects/firmware-flashing": "---\ntitle: Web Serial USB Firmware Flashing\ndescription: In-browser USB firmware installation powered by esptool-js and Web Serial API.\n---\n\nConnect an ESP32 or ESP8266 board via USB cable to a Chromium-based browser, select the serial COM port, and flash compiled `.bin` firmware directly without installing toolchains.\n",
  "en/projects/replicable-projects": "---\ntitle: Replicable Projects\ndescription: Step-by-step DIY IoT guides, materials BOM, 3D CAD viewer, and one-click USB flashing.\n---\n\nAdministrators can document complete IoT projects with markdown steps, bill of materials with purchase links, interactive 3D housing models (`.glb`/`.stl`), and flashable firmware binaries.\n",
  "en/protocols/mqtt": "---\ntitle: MQTT Ingestion (EMQX)\ndescription: Messaging protocol specifications for hardware devices and simulations.\n---\n\n## 🔐 Credentials\n\n- **Username**: Sensor UUID (e.g., `4c40ea57-43e0-4ee2-a8d5-77aae4fc387b`)\n- **Password**: Full cryptographic API Key (`betty_live_...`)\n- **Topic**: `betty/sensor/<SENSOR_UUID>/data`\n\n---\n\n## 📦 JSON Payload Specification\n\n```json\n{\n  \"temperature\": 23.8,\n  \"humidity\": 55.4,\n  \"pressure\": 1013.25,\n  \"origin_type\": \"sensor\"\n}\n```\n",
  "en/protocols/rest-api": "---\ntitle: REST API Reference\ndescription: HTTP endpoint catalog, authentication headers, and standard response envelopes.\n---\n\n## 🔒 Authentication\n\nInclude the JWT token in the `Authorization` header:\n\n```http\nAuthorization: Bearer <YOUR_ACCESS_TOKEN>\n```\n\n---\n\n## 📦 Standard Response Envelope (`ApiResponseDto`)\n\n```json\n{\n  \"success\": true,\n  \"message\": \"Success\",\n  \"data\": { ... },\n  \"timestamp\": \"2026-08-17T04:45:00.000Z\"\n}\n```\n",
  "en/protocols/websocket": "---\ntitle: Real-Time WebSocket Gateway\ndescription: Low-latency bidirectional subscriptions using Socket.IO.\n---\n\nConnect to `ws://<HOST>:3000/realtime` and join rooms per sensor:\n\n```javascript\nimport { io } from 'socket.io-client';\n\nconst socket = io('http://localhost:3000/realtime', {\n  transports: ['websocket'],\n});\n\nsocket.on('connect', () => {\n  socket.emit('subscribe:sensor', { sensorId: '4c40ea57-43e0-4ee2-a8d5-77aae4fc387b' });\n});\n\nsocket.on('sensor:data', (data) => {\n  console.log('Telemetry received:', data);\n});\n```\n",
  "en/sdks/arduino-cpp": "---\ntitle: Arduino / C++ Client\ndescription: Reusable C++ class for ESP32 and ESP8266 devices.\n---\n\nInclude `BettyClient.h` in your microcontroller project to handle WiFi connection, MQTT reconnection loops, and JSON serialization automatically.\n",
  "en/sdks/nodejs-ts": "---\ntitle: Node.js / TypeScript Client\ndescription: Connecting Node.js applications to Betty via MQTT and WebSockets.\n---\n\n```typescript\nimport mqtt from 'mqtt';\n\nconst client = mqtt.connect('mqtt://localhost:1883', {\n  username: 'YOUR_SENSOR_UUID',\n  password: 'betty_live_...',\n});\n\nclient.on('connect', () => {\n  console.log('Connected to Betty MQTT');\n  client.publish('betty/sensor/YOUR_SENSOR_UUID/data', JSON.stringify({\n    temperature: 24.5,\n    humidity: 55.0,\n    origin_type: 'sensor'\n  }));\n});\n```\n",
  "en/sdks/python": "---\ntitle: Python Client\ndescription: Streaming telemetry from Python applications with paho-mqtt.\n---\n\n```python\nimport paho.mqtt.client as mqtt\nimport json, time\n\nclient = mqtt.Client(client_id=\"python_client\")\nclient.username_pw_set(username=\"YOUR_SENSOR_UUID\", password=\"betty_live_...\")\nclient.connect(\"localhost\", 1883)\n\nclient.publish(\"betty/sensor/YOUR_SENSOR_UUID/data\", json.dumps({\n    \"temperature\": 23.4,\n    \"humidity\": 61.2,\n    \"origin_type\": \"sensor\"\n}))\n```\n",
  "en/security/api-keys": "---\ntitle: API Key Cryptographic Management\ndescription: How per-sensor keys are generated, hashed with SHA-256, and audited.\n---\n\nAPI keys are generated with high-entropy CSPRNG (`betty_live_...`). Betty only stores the SHA-256 hash in `sensors.api_key_hash`. Raw API keys are never written to disk or printed in server logs.\n",
  "en/security/rbac-roles": "---\ntitle: Roles and Permissions (RBAC)\ndescription: Unified relational role-based access control for platform and team workspaces.\n---\n\n## 🏛️ 1. System Roles (`scope: system`)\n\n- `admin`: Full platform control, user management, and system auditing.\n- `user`: Standard user with personal sensor and dashboard creation rights.\n\n---\n\n## 👥 2. Team Roles (`scope: team`)\n\n- `owner`: Full workspace control, billing/deletion, member management.\n- `team_admin`: Manage shared sensors, dashboards, and invitations.\n- `member`: Access shared devices, build dashboards, stream data.\n- `viewer`: Read-only observer.\n",
  "getting-started/architecture": "---\ntitle: Arquitectura del Sistema\ndescription: Conoce los componentes centrales, flujo de datos y modelo de capas de Betty PaaS.\n---\n\nBetty está construida siguiendo principios de **Clean Architecture (Arquitectura Hexagonal)** y microservicios modulares para garantizar alta disponibilidad y throughput masivo.\n\n---\n\n## 🏛️ Diagrama de Flujo de Ingesta y Tiempo Real\n\n```\n[Dispositivo Físico / ESP32]          [Simulación 3D / Metaverso]\n            │                                     │\n            └───────────────┬─────────────────────┘\n                            │ MQTT Publish (betty/sensor/:id/data)\n                            ▼\n                    ┌───────────────┐\n                    │    EMQX 5.8   │◄── HTTP Auth (POST /api/mqtt/auth)\n                    │  MQTT Broker  │\n                    └───────┬───────┘\n                            │ Webhook HTTP (POST /api/mqtt/webhook)\n                            ▼\n                    ┌───────────────┐\n                    │   Betty API   │ (NestJS)\n                    └───────┬───────┘\n            ┌───────────────┴───────────────┐\n            ▼                               ▼\n    ┌───────────────┐               ┌───────────────┐\n    │  PostgreSQL   │               │   Dragonfly   │\n    │  TimescaleDB  │               │ Cache/PubSub  │\n    └───────────────┘               └───────┬───────┘\n                                            │ Pub/Sub Channel\n                                            ▼\n                                    ┌───────────────┐\n                                    │ Socket.IO WSS │\n                                    │    Gateway    │\n                                    └───────┬───────┘\n                                            │ Real-time Push\n                                            ▼\n                                    [Cliente Web / Dashboards]\n```\n\n---\n\n## 🧩 Componentes de la Infraestructura\n\n### 1. Ingesta de Datos: EMQX Broker (5.8)\n- Broker MQTT escalable capaz de gestionar millones de conexiones concurrentes.\n- Cuando un dispositivo se conecta, EMQX consulta a `betty-api` mediante HTTP webhook (`POST /api/mqtt/auth`) verificando el ID del sensor y el hash de la API Key.\n- Al recibir un mensaje en `betty/sensor/:id/data`, EMQX reenvía el payload a `betty-api` vía `POST /api/mqtt/webhook`.\n\n### 2. Capa de Negocio: Betty API (NestJS)\n- Procesa el payload JSON, valida los tipos y persiste la lectura en la base de datos.\n- Invalida la caché de lecturas recientes del sensor en Dragonfly.\n- Publica el evento en el canal interno `sensor:<id>:data`.\n\n### 3. Persistencia de Series Temporales: TimescaleDB + PostgreSQL 16\n- Utiliza **Hypertables** particionadas automáticamente por tiempo (`recorded_at`).\n- Permite agregaciones hiper-rápidas sobre miles de millones de filas históricas con Drizzle ORM.\n\n### 4. Caché y Bus de Mensajería: Dragonfly\n- Servidor en memoria compatible con Redis pero con arquitectura multihilo.\n- Maneja el sistema Pub/Sub que comunica el proceso de ingesta con el Gateway de WebSockets.\n\n### 5. Distribución en Tiempo Real: Socket.IO Gateway\n- Los clientes web suscritos a la sala `sensor:<id>` reciben la actualización inmediatamente con latencia menor a 15ms.\n",
  "getting-started/introduction": "---\ntitle: Introducción a Betty PaaS\ndescription: Visión general de Betty, la plataforma abierta de IoT y Gemelos Digitales.\n---\n\n**Betty PaaS** es una plataforma como servicio (PaaS) de código abierto diseñada para la ingesta de telemetría de alto rendimiento, el procesamiento de series temporales y la sincronización en tiempo real con entornos virtuales, gemelos digitales y metaversos.\n\n---\n\n## 🎯 ¿Por qué Betty?\n\nEl desarrollo de soluciones IoT tradicionales a menudo enfrenta desafíos complejos:\n- Servidores que no escalan ante ráfagas de datos MQTT.\n- Bases de datos relacionales lentas para consultas sobre millones de registros históricos.\n- Desconexión entre los dispositivos físicos de hardware y los modelos virtuales de simulación 3D.\n- Dificultad para que los usuarios finales carguen firmware sin instalar cadenas de herramientas complejas en su ordenador.\n\nBetty resuelve estos problemas unificando:\n1. **Ingesta Ultrarrápida**: Broker MQTT (**EMQX**) con autenticación criptográfica vía HTTP.\n2. **Persistencia Optimizada**: **PostgreSQL 16 + TimescaleDB** con hypertables particionadas por tiempo.\n3. **Caché y Mensajería Multihilo**: **Dragonfly** (compatible con Redis) para Pub/Sub y caché de consultas.\n4. **Visualización y Colaboración**: Dashboards configurables en tiempo real con WebSockets y soporte de equipos con roles RBAC (`owner`, `team_admin`, `member`, `viewer`).\n5. **Instalación Web USB**: Carga de firmware binario directamente desde el navegador mediante la API Web Serial y visualizador de modelos 3D interactivos (.glb/.stl).\n\n---\n\n## 👥 Casos de Uso\n\n- **Monitoreo Industrial y Ambiental**: Registro continuo de sensores de temperatura, humedad, calidad de aire, vibración y presión.\n- **Gemelos Digitales Universitarios y Empresariales**: Réplicas virtuales 3D de laboratorios, edificios inteligentes o maquinaria en Three.js o Unity.\n- **Proyectos de Hardware DIY & Makers**: Publicación de proyectos de electrónica guiados paso a paso con piezas imprimibles en 3D y flasheo de firmware con un solo clic.\n- **Simulaciones de Metaverso**: Ingesta de telemetría generada desde simulaciones en tiempo real clasificada como origen `metaverso`.\n",
  "getting-started/quickstart": "---\ntitle: Inicio Rápido en 5 Minutos\ndescription: Aprende a registrar tu primer sensor y enviar telemetría a Betty en minutos.\n---\n\nEn esta guía rápida conectarás tu primer dispositivo o simulación a Betty y verás los datos reflejados en tiempo real.\n\n---\n\n## 📋 Requisitos Previos\n\n- Tener acceso a la plataforma Betty (ej: `http://localhost:3001` en local).\n- Cliente MQTT (como `mosquitto_pub`, un script en Python o un microcontrolador ESP32).\n\n---\n\n## 🚀 Paso 1: Crea tu Cuenta y Registra un Sensor\n\n1. Inicia sesión en la consola de Betty.\n2. Ve a la sección **Sensores** y haz clic en **+ Nuevo Sensor**.\n3. Ingresa un nombre (ej. `Sensor Laboratorio 1`) y selecciona el tipo de origen:\n   - **Físico (Sensor)**: Para placas de hardware reales (ESP32, Arduino, Raspberry Pi).\n   - **Metaverso / Simulación**: Para entornos virtuales o simuladores 3D.\n4. Al guardar, Betty generará una **API Key criptográfica** con el formato:\n   ```bash\n   betty_live_a1b2c3d4e5f6...\n   ```\n   > ⚠️ **IMPORTANTE**: Copia y guarda tu API Key de inmediato. Por motivos de seguridad, nunca se volverá a mostrar en texto plano.\n\n---\n\n## 📡 Paso 2: Publica Datos vía MQTT\n\nEl broker EMQX escucha por defecto en el puerto `1883`.\n\n### Parámetros de Conexión:\n- **Broker Host**: `localhost` (o la IP/dominio de tu servidor)\n- **Puerto**: `1883` (TCP)\n- **Usuario (`Username`)**: El ID del sensor (UUID, ej. `4c40ea57-43e0-4ee2-a8d5-77aae4fc387b`)\n- **Contraseña (`Password`)**: Tu API Key completa (`betty_live_...`)\n- **Tópico MQTT**:\n  ```\n  betty/sensor/<sensorId>/data\n  ```\n\n### Ejemplo con `mosquitto_pub`:\n\n```bash\nmosquitto_pub \\\n  -h localhost \\\n  -p 1883 \\\n  -u \"4c40ea57-43e0-4ee2-a8d5-77aae4fc387b\" \\\n  -P \"betty_live_xxxxxxxxxxxxxxxxxxxxxxxx\" \\\n  -t \"betty/sensor/4c40ea57-43e0-4ee2-a8d5-77aae4fc387b/data\" \\\n  -m '{\"temperature\": 24.5, \"humidity\": 60.2, \"origin_type\": \"sensor\"}'\n```\n\n---\n\n## 📊 Paso 3: Visualiza los Datos en Vivo\n\n1. Abre el sensor en la consola web de Betty.\n2. Observarás cómo la gráfica temporal y la tabla de lecturas se actualizan automáticamente en tiempo real mediante WebSockets.\n3. Puedes añadir este sensor a cualquier **Dashboard** con widgets de aguja (*gauge*), series temporales (*line chart*) o métricas KPI.\n",
  "hardware/esp32": "---\ntitle: Guía de Conexión ESP32 (C++/Arduino)\ndescription: Código completo y configuración para conectar placas ESP32 a Betty PaaS.\n---\n\nEl ESP32 es el microcontrolador recomendado para Betty debido a su conectividad WiFi dual, aceleración criptográfica y bajo consumo.\n\n---\n\n## 📦 Librerías Necesarias (Arduino IDE / PlatformIO)\n\nInstala las siguientes librerías desde el Gestor de Librerías:\n- `PubSubClient` (por Nick O'Leary)\n- `ArduinoJson` (v6 o v7 por Benoît Blanchon)\n\n---\n\n## 💻 Código Fuente de Ejemplo\n\n```cpp\n#include <WiFi.h>\n#include <PubSubClient.h>\n#include <ArduinoJson.h>\n\n// 1. Configuración de Red WiFi\nconst char* ssid = \"TU_WIFI_SSID\";\nconst char* password = \"TU_WIFI_PASSWORD\";\n\n// 2. Configuración de Betty MQTT Broker\nconst char* mqtt_server = \"192.168.1.100\"; // IP o dominio de tu servidor Betty\nconst int mqtt_port = 1883;\n\n// 3. Credenciales del Sensor en Betty\nconst char* sensor_id = \"4c40ea57-43e0-4ee2-a8d5-77aae4fc387b\"; // UUID\nconst char* api_key = \"betty_live_a1b2c3d4e5f6g7h8...\";          // API Key completa\n\nconst char* mqtt_topic = \"betty/sensor/4c40ea57-43e0-4ee2-a8d5-77aae4fc387b/data\";\n\nWiFiClient espClient;\nPubSubClient client(espClient);\n\nunsigned long lastMsg = 0;\nconst long interval = 5000; // Enviar telemetría cada 5 segundos\n\nvoid setup_wifi() {\n  delay(10);\n  Serial.println();\n  Serial.print(\"Conectando a \");\n  Serial.println(ssid);\n\n  WiFi.mode(WIFI_STA);\n  WiFi.begin(ssid, password);\n\n  while (WiFi.status() != WL_CONNECTED) {\n    delay(500);\n    Serial.print(\".\");\n  }\n\n  Serial.println(\"\");\n  Serial.println(\"WiFi conectado. IP: \");\n  Serial.println(WiFi.localIP());\n}\n\nvoid reconnect() {\n  while (!client.connected()) {\n    Serial.print(\"Conectando a Betty MQTT Broker...\");\n    // Conectar usando sensor_id como usuario y api_key como contraseña\n    if (client.connect(sensor_id, sensor_id, api_key)) {\n      Serial.println(\" ¡Conectado exitosamente!\");\n    } else {\n      Serial.print(\" Falló conexión, rc=\");\n      Serial.print(client.state());\n      Serial.println(\" Reintentando en 5 segundos...\");\n      delay(5000);\n    }\n  }\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  setup_wifi();\n  client.setServer(mqtt_server, mqtt_port);\n}\n\nvoid loop() {\n  if (!client.connected()) {\n    reconnect();\n  }\n  client.loop();\n\n  unsigned long now = millis();\n  if (now - lastMsg > interval) {\n    lastMsg = now;\n\n    // Simular lecturas de sensores (o leer sensores reales como DHT22 o BME280)\n    float temp = 22.0 + (random(0, 100) / 10.0);\n    float hum = 50.0 + (random(0, 200) / 10.0);\n\n    // Crear JSON\n    StaticJsonDocument<200> doc;\n    doc[\"temperature\"] = temp;\n    doc[\"humidity\"] = hum;\n    doc[\"origin_type\"] = \"sensor\";\n\n    char buffer[256];\n    serializeJson(doc, buffer);\n\n    // Publicar en el topic de Betty\n    Serial.print(\"Publicando datos: \");\n    Serial.println(buffer);\n    client.publish(mqtt_topic, buffer);\n  }\n}\n```\n",
  "hardware/esp8266": "---\ntitle: Guía de Conexión ESP8266 (NodeMCU / Wemos D1)\ndescription: Configuración y ejemplo para placas ESP8266 conectadas a Betty.\n---\n\nLas placas basadas en **ESP8266** (NodeMCU v2/v3, Wemos D1 Mini) son ideales para nodos de bajo costo.\n\n---\n\n## 💻 Código Fuente de Ejemplo\n\n```cpp\n#include <ESP8266WiFi.h>\n#include <PubSubClient.h>\n#include <ArduinoJson.h>\n\nconst char* ssid = \"TU_WIFI_SSID\";\nconst char* password = \"TU_WIFI_PASSWORD\";\n\nconst char* mqtt_server = \"192.168.1.100\";\nconst int mqtt_port = 1883;\n\nconst char* sensor_id = \"tu-sensor-uuid\";\nconst char* api_key = \"betty_live_...\";\nconst char* mqtt_topic = \"betty/sensor/tu-sensor-uuid/data\";\n\nWiFiClient espClient;\nPubSubClient client(espClient);\n\nvoid setup_wifi() {\n  delay(10);\n  WiFi.begin(ssid, password);\n  while (WiFi.status() != WL_CONNECTED) {\n    delay(500);\n    Serial.print(\".\");\n  }\n  Serial.println(\"\\nWiFi Conectado!\");\n}\n\nvoid reconnect() {\n  while (!client.connected()) {\n    if (client.connect(sensor_id, sensor_id, api_key)) {\n      Serial.println(\"Conectado a Betty MQTT!\");\n    } else {\n      delay(5000);\n    }\n  }\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  setup_wifi();\n  client.setServer(mqtt_server, mqtt_port);\n}\n\nvoid loop() {\n  if (!client.connected()) reconnect();\n  client.loop();\n\n  static unsigned long lastTime = 0;\n  if (millis() - lastTime > 10000) {\n    lastTime = millis();\n\n    StaticJsonDocument<150> doc;\n    doc[\"temperature\"] = 25.4;\n    doc[\"humidity\"] = 48.2;\n    doc[\"origin_type\"] = \"sensor\";\n\n    char buffer[200];\n    serializeJson(doc, buffer);\n    client.publish(mqtt_topic, buffer);\n  }\n}\n```\n",
  "hardware/sensors-guide": "---\ntitle: Sensores Físicos Compatibles\ndescription: Lista y diagramas de conexionado para sensores populares en proyectos IoT.\n---\n\nBetty es agnóstica al hardware: cualquier sensor conectado a un microcontrolador que transmita datos en formato JSON es 100% compatible.\n\n---\n\n## 🌡️ Sensores de Temperatura y Humedad\n\n### 1. BME280 (I2C)\n- **Mide**: Temperatura, Humedad y Presión Atmosférica.\n- **Protocolo**: I2C (`SDA` en Pin 21, `SCL` en Pin 22 en ESP32).\n- **Campos JSON recomendados**:\n  ```json\n  {\n    \"temperature\": 23.4,\n    \"humidity\": 58.2,\n    \"pressure\": 1013.25,\n    \"altitude\": 120.5\n  }\n  ```\n\n### 2. DHT11 / DHT22 (Digital)\n- **Mide**: Temperatura y Humedad.\n- **Protocolo**: Pin digital con resistencia pull-up de 10k.\n\n---\n\n## ⚡ Sensores de Movimiento y Orientación\n\n### MPU6050 (Acelerómetro + Giroscopio 6-DOF)\n- **Mide**: Aceleración (X, Y, Z) y Velocidad Angular.\n- **Ideal para**: Gemelos digitales 3D en tiempo real (orientación de maquinaria, drones, robots).\n- **Campos JSON**:\n  ```json\n  {\n    \"accel_x\": 0.02,\n    \"accel_y\": -0.98,\n    \"accel_z\": 0.12,\n    \"gyro_x\": 1.45,\n    \"gyro_y\": -0.32,\n    \"gyro_z\": 0.05\n  }\n  ```\n\n---\n\n## 💡 Sensores Ambientales y de Energía\n\n- **BH1750**: Sensor de luminosidad digital en Lux.\n- **PZEM-004T / INA219**: Medidores de voltaje, corriente (Amperios) y consumo eléctrico (Watts).\n- **MQ-135 / MQ-2**: Calidad del aire y detección de gases/humo.\n",
  "metaverses/digital-twins": "---\ntitle: Concepto de Gemelos Digitales en Betty\ndescription: Entiende la correlación entre flujos de datos de hardware físico y entornos virtuales 3D.\n---\n\nUn **Gemelo Digital (*Digital Twin*)** es una representación virtual viva de un objeto, espacio o sistema físico que se actualiza a partir de datos en tiempo real.\n\n---\n\n## 🎭 Clasificación de Origen de Datos\n\nBetty incorpora soporte nativo para clasificar la telemetría según su procedencia:\n\n1. **Origen Físico (`origin_type: \"sensor\"`)**:\n   - Lecturas reales provenientes de sensores de hardware conectados en el mundo real.\n2. **Origen Virtual / Metaverso (`origin_type: \"metaverso\"`)**:\n   - Datos emitidos desde simulaciones físicas, motores 3D, cálculos predictivos o entornos de realidad virtual/aumentada.\n\n---\n\n## 🔄 Flujo Bidireccional de un Gemelo Digital\n\n```\n┌─────────────────────────┐                ┌─────────────────────────┐\n│     Mundo Físico        │                │     Mundo Virtual       │\n│  - Sensores IoT         │── Telemetría ─►│  - Modelo 3D (Three.js) │\n│  - Actuadores / Motores │◄── Comandos ───│  - Simulación y Física  │\n└─────────────────────────┘                └─────────────────────────┘\n```\n\nCon Betty puedes:\n- Escuchar los eventos del sensor físico vía WebSocket.\n- Modificar en tiempo real la animación, posición, rotación, color o emisión lumínica del modelo 3D según los valores recibidos.\n- Comparar las métricas reales del sensor contra el comportamiento esperado de la simulación.\n",
  "metaverses/threejs-integration": "---\ntitle: Integración 3D en Tiempo Real con Three.js\ndescription: Cómo conectar un modelo 3D GLTF/GLB a la telemetría en vivo de Betty PaaS.\n---\n\nEsta guía muestra cómo vincular un visor 3D interactivo en la web para que responda dinámicamente a las lecturas de los sensores.\n\n---\n\n## 💻 Ejemplo con React Three Fiber + Socket.IO\n\n```tsx\nimport React, { useEffect, useRef, useState } from \"react\";\nimport { Canvas } from \"@react-three/fiber\";\nimport { OrbitControls, useGLTF } from \"@react-three/drei\";\nimport { io } from \"socket.io-client\";\nimport * as THREE from \"three\";\n\nfunction DigitalTwinModel({ sensorId }: { sensorId: string }) {\n  const { scene } = useGLTF(\"/modelos/motor_industrial.glb\");\n  const [temperature, setTemperature] = useState<number>(20);\n  const meshRef = useRef<THREE.Group>(null);\n\n  useEffect(() => {\n    // 1. Conectar a Betty Realtime Gateway\n    const socket = io(\"http://localhost:3000/realtime\", {\n      transports: [\"websocket\"],\n    });\n\n    socket.on(\"connect\", () => {\n      console.log(\"Conectado al gemelo digital\");\n      socket.emit(\"subscribe:sensor\", { sensorId });\n    });\n\n    // 2. Escuchar telemetría en tiempo real\n    socket.on(\"sensor:data\", (data) => {\n      if (data.payload?.temperature !== undefined) {\n        setTemperature(data.payload.temperature);\n      }\n    });\n\n    return () => {\n      socket.disconnect();\n    };\n  }, [sensorId]);\n\n  // Modificar color del material según la temperatura recibida\n  useEffect(() => {\n    scene.traverse((child) => {\n      if ((child as THREE.Mesh).isMesh) {\n        const mesh = child as THREE.Mesh;\n        if (mesh.material && \"color\" in mesh.material) {\n          // Cambiar a rojo si supera 50°C\n          const color = temperature > 50 ? \"#ef4444\" : \"#3b82f6\";\n          (mesh.material as THREE.MeshStandardMaterial).color.set(color);\n        }\n      }\n    });\n  }, [temperature, scene]);\n\n  return <primitive ref={meshRef} object={scene} scale={1.5} />;\n}\n\nexport function DigitalTwinViewer() {\n  return (\n    <div className=\"w-full h-125 bg-slate-900 rounded-xl overflow-hidden\">\n      <Canvas camera={{ position: [0, 2, 5], fov: 45 }}>\n        <ambientLight intensity={0.7} />\n        <directionalLight position={[10, 10, 5]} intensity={1} />\n        <DigitalTwinModel sensorId=\"4c40ea57-43e0-4ee2-a8d5-77aae4fc387b\" />\n        <OrbitControls enableDamping />\n      </Canvas>\n    </div>\n  );\n}\n```\n",
  "metaverses/unity-unreal": "---\ntitle: Integración con Motores 3D (Unity / Unreal Engine)\ndescription: Cómo conectar entornos de simulación en Unity y Unreal a la ingesta de Betty.\n---\n\nLos motores de juego como Unity y Unreal Engine permiten construir experiencias inmersivas de gemelos digitales y metaversos que pueden transmitir o recibir datos de Betty.\n\n---\n\n## 🎮 Integración con Unity (C#)\n\nPuedes utilizar la librería **M2Mqtt** o paquetes WebSocket para comunicarte con Betty.\n\n### Ejemplo de Publicación en Unity (C#):\n\n```csharp\nusing UnityEngine;\nusing uPLibrary.Networking.M2Mqtt;\nusing uPLibrary.Networking.M2Mqtt.Messages;\nusing System.Text;\n\npublic class BettyTwinSender : MonoBehaviour\n{\n    private MqttClient client;\n    public string brokerIp = \"127.0.0.1\";\n    public string sensorId = \"tu-sensor-uuid\";\n    public string apiKey = \"betty_live_...\";\n\n    void Start()\n    {\n        client = new MqttClient(brokerIp);\n        byte code = client.Connect(sensorId, sensorId, apiKey);\n        Debug.Log(\"Conectado a Betty MQTT con código: \" + code);\n    }\n\n    void Update()\n    {\n        // Enviar posición X, Y, Z del objeto cada segundo\n        if (Time.frameCount % 60 == 0 && client != null && client.IsConnected)\n        {\n            Vector3 pos = transform.position;\n            string payload = $\"{{\\\"pos_x\\\": {pos.x}, \\\"pos_y\\\": {pos.y}, \\\"pos_z\\\": {pos.z}, \\\"origin_type\\\": \\\"metaverso\\\"}}\";\n            \n            client.Publish(\"betty/sensor/\" + sensorId + \"/data\", Encoding.UTF8.GetBytes(payload));\n        }\n    }\n}\n```\n\n---\n\n## 🕹️ Integración con Unreal Engine (Blueprints / C++)\n\n- Utiliza el plugin **MQTT for Unreal** del Marketplace.\n- Configura el cliente con el ID del sensor y el hash de la API Key en el puerto `1883`.\n- Publica en `betty/sensor/:id/data` con `origin_type: \"metaverso\"`.\n",
  "projects/firmware-flashing": "---\ntitle: Flasheo de Firmware por Web Serial (USB)\ndescription: Cómo funciona la instalación de firmware directa desde el navegador sin instalar herramientas locales.\n---\n\nBetty integra la **Web Serial API** y la librería `esptool-js` para permitir a los usuarios programar sus placas ESP32 y ESP8266 conectándolas directamente por cable USB a su ordenador.\n\n---\n\n## 🧭 ¿Cómo Funciona el Proceso?\n\n```\n[Navegador Web (Chromium)] ─── Web Serial API (USB) ───► [Microcontrolador ESP32]\n           │\n           │ HTTP GET /api/files/firmware/...\n           ▼\n[Betty API Server (Almacenamiento Local)]\n```\n\n1. El usuario conecta su placa ESP32 por USB y hace clic en **\"Flashear Firmware\"**.\n2. El navegador solicita permiso para acceder al puerto COM serie mediante `navigator.serial.requestPort()`.\n3. Betty establece conexión con el bootloader del ESP a una velocidad de **921600 baudios**.\n4. Se detecta el modelo exacto de chip (ej: `ESP32-D0WD-V3`).\n5. Se descarga el archivo `.bin` compilado desde el servidor de Betty y se escribe en la dirección de memoria especificada (por defecto `0x10000`).\n6. El microcontrolador se reinicia automáticamente y comienza a ejecutar el firmware.\n\n---\n\n## 🛠️ Cómo Compilar y Subir Firmware como Administrador\n\n1. En Arduino IDE o PlatformIO, compila tu sketch y exporta los binarios compilados (`.bin`).\n2. Entra a la consola de administración en `/admin/projects/:id/edit`.\n3. Ve a la pestaña **Firmware** y haz clic en **+ Subir Nuevo Firmware**.\n4. Selecciona la familia del chip (`ESP32`, `ESP8266`, etc.), la versión semver (ej: `1.0.0`) y el offset de memoria (`0x10000`).\n5. Sube el archivo `.bin`. El binario quedará almacenado localmente en el servidor (`uploads/firmware/`) listo para flashear.\n",
  "projects/replicable-projects": "---\ntitle: Proyectos Replicables en Betty\ndescription: Guía para crear y publicar proyectos guiados con modelos 3D y firmware instalable.\n---\n\nEl módulo de **Proyectos Replicables** permite a los administradores documentar proyectos IoT completos para que la comunidad o los miembros del equipo puedan ensamblarlos sin fricción.\n\n---\n\n## 📋 Estructura de un Proyecto Replicable\n\nCada proyecto incluye:\n\n1. **Información General**: Título, descripción, nivel de dificultad (`beginner`, `intermediate`, `advanced`), microcontrolador requerido (ej: `ESP32`) y foto de portada.\n2. **Pasos Guiados (*Steps*)**: Pasos de ensamblaje ordenados cronológicamente con explicaciones detalladas en Markdown, fotos ilustrativas y enlaces a video opcionales.\n3. **Lista de Materiales (*BOM*)**: Componentes necesarios, cantidades, costos estimados y enlaces directos de compra.\n4. **Modelo 3D Interactivo**: Archivo `.glb`, `.gltf` o `.stl` de la carcasa o circuito renderizable en 3D en el navegador.\n5. **Firmware USB**: Binario compilado `.bin` alojado en el servidor para que los usuarios puedan flashearlo directamente por USB con un solo clic.\n",
  "protocols/mqtt": "---\ntitle: Ingesta MQTT (EMQX)\ndescription: Protocolo de mensajería para sensores IoT y transmisiones de telemetría.\n---\n\nEl protocolo MQTT es el estándar principal para enviar telemetría de dispositivos hacia Betty PaaS.\n\n---\n\n## 🔐 Autenticación MQTT\n\nBetty implementa autenticación HTTP delegada en el broker EMQX. Cada conexión debe autenticarse con las siguientes credenciales:\n\n- **Username**: El UUID del sensor registrado (ej: `4c40ea57-43e0-4ee2-a8d5-77aae4fc387b`).\n- **Password**: La API Key criptográfica completa (ej: `betty_live_1234567890abcdef...`).\n- **Client ID**: Cualquier identificador único o el mismo UUID del sensor.\n\n---\n\n## 📬 Formato del Tópico MQTT\n\nLos sensores solo tienen permiso para publicar en su propio tópico dedicado:\n\n```\nbetty/sensor/<SENSOR_UUID>/data\n```\n\n> 💡 **Nota**: Intentar publicar en el tópico de otro sensor o sin credenciales válidas resultará en la desconexión inmediata por parte de EMQX.\n\n---\n\n## 📦 Estructura del Payload JSON\n\nEl payload publicado debe ser un objeto JSON válido. Betty extrae y almacena todos los campos numéricos y de texto automáticamente.\n\n### Ejemplo de Payload Básico:\n\n```json\n{\n  \"temperature\": 23.8,\n  \"humidity\": 55.4,\n  \"pressure\": 1013.25,\n  \"battery_voltage\": 3.72,\n  \"origin_type\": \"sensor\"\n}\n```\n\n### Campos Especiales:\n\n| Campo | Tipo | Requerido | Descripción |\n| :--- | :--- | :--- | :--- |\n| `origin_type` | `string` | No (default: `\"sensor\"`) | Clasifica el dato como `\"sensor\"` (dispositivo físico) o `\"metaverso\"` (simulación virtual). |\n| `recorded_at` | `string (ISO 8601)` | No (default: `now()`) | Timestamp explícito de la lectura si el dispositivo almacena datos sin conexión y los sincroniza después. |\n\n---\n\n## ⚡ Niveles de QoS Recomendados\n\n- **QoS 0 (At most once)**: Para sensores de alta frecuencia (ej: acelerómetros o telemetría continua de posición).\n- **QoS 1 (At least once)**: Recomendado para mediciones periódicas estándar (temperatura, energía, alarmas).\n",
  "protocols/rest-api": "---\ntitle: Referencia de API REST\ndescription: Especificación técnica de endpoints HTTP, autenticación y respuestas.\n---\n\nLa API REST de Betty opera en el prefijo `/api` y utiliza formato JSON tanto para peticiones como para respuestas.\n\n---\n\n## 🔒 Autenticación\n\nLos endpoints protegidos requieren una cabecera `Authorization` con token Bearer JWT:\n\n```http\nAuthorization: Bearer <TU_ACCESS_TOKEN>\n```\n\n---\n\n## 📦 Formato Estándar de Respuesta (`ApiResponseDto`)\n\nTodas las respuestas de la API están envueltas en una estructura uniforme:\n\n### Respuesta Exitosa:\n```json\n{\n  \"success\": true,\n  \"message\": \"Operación exitosa\",\n  \"data\": { ... },\n  \"timestamp\": \"2026-08-17T04:45:00.000Z\"\n}\n```\n\n### Respuesta de Error:\n```json\n{\n  \"success\": false,\n  \"statusCode\": 401,\n  \"path\": \"/api/sensors\",\n  \"message\": \"No autorizado\",\n  \"errors\": null,\n  \"timestamp\": \"2026-08-17T04:45:00.000Z\"\n}\n```\n\n---\n\n## 📋 Catálogo Principal de Endpoints\n\n### 🔑 Autenticación (`/api/auth`)\n- `POST /api/auth/register`: Registro con email, nombre y contraseña.\n- `POST /api/auth/login`: Inicio de sesión (retorna accessToken y refreshToken).\n- `POST /api/auth/refresh-token`: Renovación de access token.\n- `POST /api/auth/forgot-password`: Solicitar correo de reseteo de contraseña.\n- `POST /api/auth/reset-password`: Restablecer contraseña con token.\n\n### 📡 Sensores (`/api/sensors`)\n- `GET /api/sensors`: Listar sensores del usuario o de sus equipos.\n- `POST /api/sensors`: Crear un nuevo sensor (retorna la `rawApiKey` por única vez).\n- `GET /api/sensors/:id`: Obtener detalles y metadatos del sensor.\n- `PATCH /api/sensors/:id`: Actualizar nombre o descripción.\n- `DELETE /api/sensors/:id`: Eliminar sensor y sus registros históricos.\n- `POST /api/sensors/:id/api-key/rotate`: Rotar la API Key y generar una nueva.\n- `POST /api/sensors/:id/api-key/revoke`: Revocar la API Key e inactivar el sensor.\n- `GET /api/sensors/:id/data`: Consultar series temporales históricas (con filtros `limit`, `from`, `to`).\n\n### 📊 Dashboards (`/api/dashboards`)\n- `GET /api/dashboards`: Listar dashboards propios y de equipos.\n- `POST /api/dashboards`: Crear nuevo dashboard.\n- `GET /api/dashboards/:id`: Obtener dashboard con widgets.\n- `PATCH /api/dashboards/:id/publish`: Alternar visibilidad pública/privada.\n- `GET /api/dashboards/public/:id`: Obtener dashboard público (sin necesidad de token).\n- `POST /api/dashboards/:id/widgets`: Agregar widget (`line_chart`, `gauge`, `table`, `map`, `metric`, `bar_chart`).\n\n### 👥 Equipos (`/api/teams`)\n- `GET /api/teams`: Listar equipos a los que pertenece el usuario.\n- `POST /api/teams`: Crear un nuevo equipo de trabajo.\n- `POST /api/teams/join/code`: Unirse a un equipo mediante código alfanumérico de 8 caracteres.\n- `POST /api/teams/join/token`: Unirse mediante enlace de invitación firmado.\n- `POST /api/teams/:id/invitations/link`: Generar enlace de invitación de 7 días.\n\n### 🧩 Proyectos Replicables (`/api/projects`)\n- `GET /api/projects`: Galería pública de proyectos con filtros de dificultad y tags.\n- `GET /api/projects/:id`: Detalle completo del proyecto con pasos, materiales, modelo 3D y firmwares.\n- `GET /api/projects/:id/firmware/:firmwareId/manifest`: Manifest JSON para flasheo con ESP Web Tools.\n",
  "protocols/websocket": "---\ntitle: WebSocket Gateway en Tiempo Real\ndescription: Conexión bidireccional y suscripciones en tiempo real con Socket.IO.\n---\n\nBetty expone un Gateway WebSocket basado en **Socket.IO** en la ruta `/realtime`, permitiendo a dashboards, gemelos digitales 3D y aplicaciones móviles recibir lecturas instantáneamente en cuanto se publican vía MQTT.\n\n---\n\n## 🔌 Endpoint de Conexión\n\n```\nws://<TU_DOMINIO_O_IP>:3000/realtime\n```\n\n---\n\n## 📡 Eventos y Suscripciones\n\nPara optimizar el ancho de banda, el gateway utiliza **salas (*rooms*)** por sensor y tablero.\n\n### 1. Suscribirse a un Sensor\n\nEnvía el evento `subscribe:sensor` con el ID del sensor:\n\n```javascript\nimport { io } from 'socket.io-client';\n\nconst socket = io('http://localhost:3000/realtime', {\n  transports: ['websocket'],\n  auth: {\n    token: 'TU_JWT_BEARER_TOKEN_AQUI' // Opcional para dashboards públicos\n  }\n});\n\nsocket.on('connect', () => {\n  console.log('Conectado al Gateway de Betty');\n  \n  // Suscribirse a la sala del sensor\n  socket.emit('subscribe:sensor', { sensorId: '4c40ea57-43e0-4ee2-a8d5-77aae4fc387b' });\n});\n\n// Escuchar datos en vivo\nsocket.on('sensor:data', (data) => {\n  console.log('Nueva lectura recibida:', data);\n  // data = { id, sensorId, payload: { temperature: 24.5, ... }, originType: 'sensor', recordedAt: '...' }\n});\n```\n\n### 2. Desuscribirse\n\n```javascript\nsocket.emit('unsubscribe:sensor', { sensorId: '4c40ea57-43e0-4ee2-a8d5-77aae4fc387b' });\n```\n\n---\n\n## 🌐 Suscripción a Tableros (Dashboards)\n\nSi tienes un dashboard con múltiples widgets, puedes suscribirte a todos los sensores del tablero en un solo comando:\n\n```javascript\nsocket.emit('subscribe:dashboard', { dashboardId: 'uuid-del-dashboard' });\n```\n",
  "sdks/arduino-cpp": "---\ntitle: Cliente Arduino / C++\ndescription: Librería y clase reutilizable en C++ para microcontroladores ESP32 y ESP8266.\n---\n\nEste módulo encapsula la conexión WiFi, el cliente MQTT de Betty y la reconexión automática en una clase limpia en C++.\n\n---\n\n## 💻 Clase Reutilizable `BettyClient.h`\n\n```cpp\n#ifndef BETTY_CLIENT_H\n#define BETTY_CLIENT_H\n\n#include <WiFi.h>\n#include <PubSubClient.h>\n#include <ArduinoJson.h>\n\nclass BettyClient {\nprivate:\n  WiFiClient _wifiClient;\n  PubSubClient _mqttClient;\n  String _sensorId;\n  String _apiKey;\n  String _topic;\n\npublic:\n  BettyClient(const char* brokerHost, int brokerPort, const char* sensorId, const char* apiKey) {\n    _sensorId = sensorId;\n    _apiKey = apiKey;\n    _topic = String(\"betty/sensor/\") + sensorId + \"/data\";\n    _mqttClient.setClient(_wifiClient);\n    _mqttClient.setServer(brokerHost, brokerPort);\n  }\n\n  void loop() {\n    if (!_mqttClient.connected()) {\n      reconnect();\n    }\n    _mqttClient.loop();\n  }\n\n  bool send(StaticJsonDocument<256>& doc) {\n    if (!doc.containsKey(\"origin_type\")) {\n      doc[\"origin_type\"] = \"sensor\";\n    }\n    char buffer[256];\n    serializeJson(doc, buffer);\n    return _mqttClient.publish(_topic.c_str(), buffer);\n  }\n\nprivate:\n  void reconnect() {\n    while (!_mqttClient.connected()) {\n      if (_mqttClient.connect(_sensorId.c_str(), _sensorId.c_str(), _apiKey.c_str())) {\n        Serial.println(\"✅ [Betty] Conectado al broker MQTT\");\n      } else {\n        Serial.print(\"❌ [Betty] Reintentando en 5s, estado=\");\n        Serial.println(_mqttClient.state());\n        delay(5000);\n      }\n    }\n  }\n};\n\n#endif\n```\n",
  "sdks/nodejs-ts": "---\ntitle: Cliente Node.js / TypeScript\ndescription: Ejemplo de integración y publicación de telemetría con Node.js y TypeScript.\n---\n\nPuedes interactuar con Betty en tus aplicaciones de servidor o microservicios usando librerías estándar como `mqtt` y `socket.io-client`.\n\n---\n\n## 📦 Instalación\n\n```bash\nnpm install mqtt socket.io-client\n```\n\n---\n\n## 📡 Ejemplo de Publicador MQTT en Node.js\n\n```typescript\nimport mqtt from 'mqtt';\n\nconst SENSOR_ID = '4c40ea57-43e0-4ee2-a8d5-77aae4fc387b';\nconst API_KEY = 'betty_live_xxxxxxxxxxxxxxxxxxxxxxxx';\nconst BROKER_URL = 'mqtt://localhost:1883';\n\nconst client = mqtt.connect(BROKER_URL, {\n  username: SENSOR_ID,\n  password: API_KEY,\n  clientId: `node_client_${Date.now()}`,\n});\n\nclient.on('connect', () => {\n  console.log('✅ Conectado a Betty MQTT Broker');\n\n  // Enviar telemetría periódica\n  setInterval(() => {\n    const payload = {\n      cpu_usage: Math.round(Math.random() * 100),\n      memory_free_mb: 2048 + Math.round(Math.random() * 500),\n      requests_per_sec: 142,\n      origin_type: 'sensor',\n    };\n\n    const topic = `betty/sensor/${SENSOR_ID}/data`;\n    client.publish(topic, JSON.stringify(payload), { qos: 1 }, (err) => {\n      if (err) console.error('Error publicando:', err);\n      else console.log('📤 Telemetría enviada:', payload);\n    });\n  }, 3000);\n});\n\nclient.on('error', (err) => {\n  console.error('❌ Error de conexión MQTT:', err);\n});\n```\n",
  "sdks/python": "---\ntitle: Cliente Python\ndescription: Script de publicación de datos y consumo de telemetría con Python.\n---\n\nPython es perfecto para scripts de ciencia de datos, Raspberry Pi y prototipado rápido con Betty.\n\n---\n\n## 📦 Instalación\n\n```bash\npip install paho-mqtt requests python-socketio[client]\n```\n\n---\n\n## 🐍 Ejemplo con `paho-mqtt`\n\n```python\nimport paho.mqtt.client as mqtt\nimport json\nimport time\nimport random\n\nSENSOR_ID = \"4c40ea57-43e0-4ee2-a8d5-77aae4fc387b\"\nAPI_KEY = \"betty_live_xxxxxxxxxxxxxxxxxxxxxxxx\"\nBROKER_HOST = \"localhost\"\nBROKER_PORT = 1883\n\nTOPIC = f\"betty/sensor/{SENSOR_ID}/data\"\n\ndef on_connect(client, userdata, flags, rc):\n    if rc == 0:\n        print(\"✅ Conectado exitosamente a Betty MQTT\")\n    else:\n        print(f\"❌ Error al conectar, código de retorno: {rc}\")\n\nclient = mqtt.Client(client_id=f\"python_node_{int(time.time())}\")\nclient.username_pw_set(username=SENSOR_ID, password=API_KEY)\nclient.on_connect = on_connect\n\nclient.connect(BROKER_HOST, BROKER_PORT, keepalive=60)\nclient.loop_start()\n\ntry:\n    while True:\n        payload = {\n            \"temperature\": round(20.0 + random.uniform(0, 10), 2),\n            \"humidity\": round(45.0 + random.uniform(0, 20), 2),\n            \"co2_ppm\": random.randint(400, 1200),\n            \"origin_type\": \"sensor\"\n        }\n        \n        client.publish(TOPIC, json.dumps(payload), qos=1)\n        print(f\"📤 Datos enviados: {payload}\")\n        time.sleep(5)\nexcept KeyboardInterrupt:\n    print(\"\\nDeteniendo cliente...\")\nfinally:\n    client.loop_stop()\n    client.disconnect()\n```\n",
  "security/api-keys": "---\ntitle: Gestión Segura de API Keys\ndescription: Cómo se generan, hashean y auditan las claves criptográficas en Betty PaaS.\n---\n\nLa seguridad en la ingesta de telemetría es fundamental en Betty. Las API Keys autentican a cada dispositivo físico o virtual de forma individual.\n\n---\n\n## 🔒 Arquitectura Criptográfica\n\n1. **Generación**: Cada clave se crea utilizando generadores de entropía criptográfica (`CryptoUtil.generateApiKey()`), produciendo una clave con el prefijo `betty_live_` y 32 bytes de alta entropía.\n2. **Hasheo Inmutable**: Betty calcula el hash **SHA-256** de la clave y almacena únicamente `api_key_hash` y los primeros 12 caracteres visibles como `api_key_prefix` en la tabla `sensors`.\n3. **Cero Texto Plano**: La clave en texto plano (`rawApiKey`) **NUNCA** se guarda en la base de datos ni se escribe en logs. Se entrega una sola vez al usuario al momento de la creación.\n4. **Validación Instantánea**: Al recibir la conexión MQTT, Betty calcula el SHA-256 de la contraseña proporcionada y la compara en tiempo constante contra el hash almacenado.\n\n---\n\n## 🔄 Rotación y Revocación\n\n- **Rotación**: En caso de sospecha de compromiso, puedes pulsar **\"Rotar API Key\"** desde la consola web. La clave antigua queda invalidada de inmediato y se entrega una nueva.\n- **Revocación**: Inactiva el sensor y rechaza cualquier paquete MQTT entrante de forma permanente.\n- **Auditoría**: Toda creación, rotación y revocación queda registrada en `api_key_audit_log`.\n",
  "security/rbac-roles": "---\ntitle: Roles y Permisos (RBAC)\ndescription: Sistema unificado de control de acceso basado en roles para la plataforma y equipos.\n---\n\nBetty implementa un modelo de **Control de Acceso Basado en Roles (RBAC)** relacional unificado en la tabla `roles` con dos ámbitos (*scopes*):\n\n---\n\n## 🏛️ 1. Roles del Sistema (`scope: system`)\n\nAsignados globalmente a cada usuario de la plataforma en `users.role_id`:\n\n| Rol | Slug | Permisos | Descripción |\n| :--- | :--- | :--- | :--- |\n| **Administrador** | `admin` | `[\"*\"]` | Control total del sistema, administración de usuarios, auditoría global y creación de proyectos replicables. |\n| **Usuario Estándar** | `user` | `[\"team:create\", \"sensor:create\", \"dashboard:create\"]` | Creación de sensores propios, tableros y equipos. |\n\n---\n\n## 👥 2. Roles de Equipo (`scope: team`)\n\nAsignados a los miembros dentro de un equipo en `team_members.role_id`:\n\n| Rol | Slug | Permisos JSONB | Capacidades |\n| :--- | :--- | :--- | :--- |\n| **Propietario (*Owner*)** | `owner` | `[\"team:*\", \"sensor:*\", \"dashboard:*\", \"member:*\"]` | Máxima autoridad del equipo, puede eliminar el equipo, transferir propiedad y expulsar miembros. |\n| **Administrador de Equipo** | `team_admin` | `[\"team:read\", \"sensor:*\", \"dashboard:*\", \"member:invite\", \"member:remove\"]` | Administra dispositivos y dashboards compartidos e invita a nuevos miembros. |\n| **Miembro** | `member` | `[\"team:read\", \"sensor:read\", \"sensor:data\", \"dashboard:create\", \"dashboard:read\"]` | Puede ver sensores, crear dashboards y consultar telemetría. |\n| **Observador (*Viewer*)** | `viewer` | `[\"team:read\", \"sensor:read\", \"dashboard:read\"]` | Acceso de solo lectura a los tableros del equipo. |\n"
};
